recipes.code:
{
  "inputs": [
    {
      "id": "tinify-api-key",
      "type": "promptString",
      "description": "Tinify.dev API key (tnf_live_* or tnf_test_*), created at https://tinify.dev/developers. Free tier: 500 operations/month.",
      "password": true
    }
  ],
  "servers": {
    "mcp": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@tinify-dev/mcp@0.1.5"
      ],
      "env": {
        "TINIFY_API_KEY": "${input:tinify-api-key}",
        "TINIFY_BASE_URL": "<tinify-base-url>"
      }
    }
  }
}
